                    // A bad or off-grid id is part of the ask that was not read (re-review R5).
                    success = errors.Count == 0,
                    count = outp.Count,
                    requested = ids.Count,
                    truncated = skipped,
                    tilesCount = Find.WorldGrid.TilesCount,
                    errors,
                    tiles = outp,
                    ticksGame = TicksGameSafe(),
                };
            });
        }

