# ------------------------------------------------------------------ transaction
class SettingsTransaction(object):
    """Record pre-mutation debug + difficulty values FIRST, change them through `set`, restore exactly
    on exit. The pre-values are read before the first write, so a half-failed prepare still restores
    to what a human had, not to a value this harness wrote."""

    DIFFICULTY_KEYS = ("threatScale", "allowBigThreats")

    def __init__(self, session):
        self.session = session
        self.pre_debug = {}
        self.pre_difficulty = {}
        self.touched_debug = []
        self.touched_difficulty = []
        self.restored = False
        # (label, fn) run at restore, newest first: things a profile ARMED that are not debug/difficulty values
        # (the wild-spawner block). A cleanup that fails is a restore problem, reported like one.
        self.cleanups = []
        self.debt = None

    def plan(self):
        """The bridge writes restore() would make, as data (WRAPUP_SETTINGS_DEBT_RESTORE_TIDY_ELF): a kill between a
        change and restore() leaves the debt on the register, and wrapup.restore replays this at the next bridge hold.
        Without it the debt's undo was prose and nothing could pay it once filed. A cleanup with no step is named in
        the debt's `unplanned`, so the replay never pays what it could not undo."""
        steps = [st for _, _, st in reversed(self.cleanups) if st]
        steps += [wrapup_debt.step("jawa/debug_settings", action="set", field=f, value=self.pre_debug[f])
                  for f in dict.fromkeys(self.touched_debug)]
        if self.touched_difficulty:
            steps.append(wrapup_debt.step("jawa/difficulty_tune", **dict(
                (k, self.pre_difficulty[k]) for k in dict.fromkeys(self.touched_difficulty))))
        return steps

    def _owe(self, what):
        # owed from the first change until restore() reads every value back: a kill between them leaves it filed
        if self.debt is None:
            self.debt = wrapup_debt.owe("setting", "SettingsTransaction forced %s" % what,
                                        "set it back to its pre-run value (debug_settings / difficulty_tune; "
                                        "difficulty was %r)" % (self.pre_difficulty,))

    def _replan(self):
        # after each change is recorded (touched_* / cleanups), so the plan covers it before the write is sent
        wrapup_debt.amend(self.debt, {"plan": self.plan(),
                                      "unplanned": [label for label, _, st in self.cleanups if not st]})

    def __enter__(self):
        self.pre_debug = read_settings(self.session)
        r = self.session.call("jawa/difficulty_tune")        # no args == read (measured)
        if r.get("success"):
            self.pre_difficulty = dict((k, r["before"][k]) for k in self.DIFFICULTY_KEYS if k in r["before"])
        return self

    def set_debug(self, field, value):
        if field not in self.pre_debug:
            raise HelperUnverified("debug field %r not present in debug_settings list" % field)
        self._owe("debug %s=%r" % (field, value))
        self.touched_debug.append(field)
        self._replan()
        r = self.session.call("jawa/debug_settings", action="set", field=field, value=value)
        now = read_settings(self.session).get(field)
        if now != value:
            raise HelperUnverified("debug_settings %s: asked %r, read back %r (success=%s)"
                                   % (field, value, now, r.get("success")))

    def set_difficulty(self, **kw):
        for k in kw:
            if k not in self.pre_difficulty:
                raise HelperUnverified("difficulty key %r not readable" % k)
        self._owe("difficulty %r" % (kw,))
        self.touched_difficulty.extend(kw)
        self._replan()
        r = self.session.call("jawa/difficulty_tune", **kw)
        after = r.get("after") or {}
        for k, v in kw.items():
            if after.get(k) != v:
                raise HelperUnverified("difficulty_tune %s: asked %r, read back %r" % (k, v, after.get(k)))

    def on_restore(self, label, fn, step=None):
        """`step` (wrapup_debt.step) is the same undo as a bridge write, for the replay after a kill."""
        self._owe(label)
        self.cleanups.append((label, fn, step))
        self._replan()

    def restore(self):
        problems = []
        for label, fn, _ in reversed(self.cleanups):
            try:
                if fn() is False:
                    problems.append("%s not undone" % label)
            except Exception as e:                              # noqa: BLE001 - reported, never swallowed silently
                problems.append("%s cleanup raised %r" % (label, e))
        self.cleanups = []
        for f in set(self.touched_debug):
            want = self.pre_debug[f]
            self.session.call("jawa/debug_settings", action="set", field=f, value=want)
            if read_settings(self.session).get(f) != want:
                problems.append("debug %s not restored to %r" % (f, want))
        if self.touched_difficulty:
            kw = dict((k, self.pre_difficulty[k]) for k in set(self.touched_difficulty))
            r = self.session.call("jawa/difficulty_tune", **kw)
            after = r.get("after") or {}
            for k, v in kw.items():
                if after.get(k) != v:
                    problems.append("difficulty %s not restored to %r" % (k, v))
        self.restored = True
        if problems:
            raise HelperUnverified("; ".join(problems))
        wrapup_debt.paid(self.debt)
        self.debt = None

    def __exit__(self, et, ev, tb):
        self.restore()
        return False


def quiet_world(session, tx, wild_spawner=True, log_raids=True):
    """The quiet-world profile for validation runs (map awareness phase 1e). Wires what exists and READS BACK what
    was actually suppressed -- a configured flag is not proof a path obeyed it:
      * storyteller_off + random_events_off (existing helpers);
      * DebugSettings.logRaidInfo = true: observation, not suppression -- every raid through
        IncidentWorker_Raid logs `Raid: <faction> <arrival> <strategy> ...` to Player.log (field VERIFIED in
        decompiled 1.6 DebugSettings via RimSage 2026-10-10; the log line per the Opus review, IncidentWorker_Raid);
      * wild-animal replenishment blocked with `jawa/wild_spawner_block` (companion, THING_LOOKUP_BUILD_OWNER_IS_NOT_PAINTER)
        when the tool exists, released by the transaction on exit; 'unavailable' otherwise, never assumed;
      * quests are NOT touched (GPT s2: ending a quest is destructive setup).
    Never raises for an unavailable piece: the evidence says which piece is missing."""
    ev = {"profile": "isolated", "quests": "not touched", "notSuppressed": list(QUIET_NOT_SUPPRESSED)}
    st = storyteller_off(session, tx)
    re_ = random_events_off(session, tx)
    ev["storyteller"] = st.evidence
    if log_raids:
        if "logRaidInfo" in tx.pre_debug:
            tx.set_debug("logRaidInfo", True)
            ev["logRaidInfo"] = "on"
        else:
            ev["logRaidInfo"] = "unavailable: field not in debug_settings list"
    if wild_spawner:
        r, err = _try_call(session, "jawa/wild_spawner_block", action="block")
        if err:
            ev["wildSpawner"] = "unavailable: %s" % err
        else:
            tx.on_restore("wild_spawner_block", lambda: bool((_try_call(session, "jawa/wild_spawner_block",
                                                                        action="release")[0] or {}).get("blocked") is False),
                          step=wrapup_debt.step("jawa/wild_spawner_block", expect={"blocked": False}, action="release"))
            g, gerr = _try_call(session, "jawa/wild_spawner_block", action="get")
            ev["wildSpawner"] = ("blocked (read back)" if g and g.get("blocked") is True
                                 else "UNVERIFIED: asked to block, read back %r" % ((g or {}).get("blocked") if g else gerr))
    settings = read_settings(session)
    ev["readBack"] = dict((k, settings.get(k)) for k in ("enableStoryteller", "enableRandomMentalStates",
                                                         "enableRandomDiseases", "logRaidInfo") if k in settings)
    d, _ = _try_call(session, "jawa/difficulty_tune")
    if d:
        ev["readBack"].update(dict((k, (d.get("before") or {}).get(k)) for k in ("threatScale", "allowBigThreats")))
    q, qerr = _try_call(session, "jawa/incident_queue_peek")
    ev["incidentQueueAfterClear"] = len(q.get("queue") or []) if q else "unavailable: %s" % qerr
    verified = (ev["readBack"].get("enableStoryteller") is False and ev["readBack"].get("enableRandomMentalStates") is False
                and (not log_raids or ev.get("logRaidInfo") != "on" or ev["readBack"].get("logRaidInfo") is True)
                and not str(ev.get("wildSpawner", "")).startswith("UNVERIFIED"))
    return HelperResult("quiet_world", acted=st.acted + re_.acted, verified=verified,
                        residue=[] if verified else ["read-back disagrees: %s" % ev["readBack"]], evidence=ev)


