                if self._watches():
                    self._note_mutation({"kind": "site_recover", "stopBy": g.result.get("stopBy"), "executed": took,
                                         "atTick": (g.result.get("stopBy") or {}).get("tick")})
                ex = min(req, took)
                left -= ex
                done += ex
                continue
            done += req if ex is None else int(ex)
            left -= req
        return {"success": True, "advanced": done}


