class SettingsTransaction(object):
    """Record pre-mutation debug + difficulty values FIRST, change them through `set`, restore exactly
    on exit. The pre-values are read before the first write, so a half-failed prepare still restores
    to what a human had, not to a value this harness wrote."""

    DIFFICULTY_KEYS = ("threatScale", "allowBigThreats")

    def __init__(self, session):
        self.session = session
        self.pre_debug = {}
        self.pre_difficulty = {}
        self.touched_debug = []
        self.touched_difficulty = []
        self.restored = False
        # (label, fn) run at restore, newest first: things a profile ARMED that are not debug/difficulty values
        # (the wild-spawner block). A cleanup that fails is a restore problem, reported like one.
        self.cleanups = []
        self.debt = None

    def plan(self):
        """The bridge writes restore() would make, as data (WRAPUP_SETTINGS_DEBT_RESTORE_TIDY_ELF): a kill between a
        change and restore() leaves the debt on the register, and wrapup.restore replays this at the next bridge hold.
        Without it the debt's undo was prose and nothing could pay it once filed. A cleanup with no step is named in
        the debt's `unplanned`, so the replay never pays what it could not undo."""
        steps = [st for _, _, st in reversed(self.cleanups) if st]
        steps += [wrapup_debt.step("jawa/debug_settings", action="set", field=f, value=self.pre_debug[f])
